// Language: English at /, Italian at /it/. Two pages, one content file each.
// No visible copy lives here: UI labels come from content (C.ui). This module holds the locale list,
// the saved choice and the switcher. No DOM access at import time: the build imports it in node.
//   - the first-visit redirect is an inline script in <head> (generated by scripts/build.mjs), so it runs before paint
//   - a saved choice (localStorage gc-lang) disables the automatic redirect for good
//   - the switcher link saves the choice on click and keeps the #hash

export const LOCALES = {
  en: { path: '/', ogLocale: 'en_US' },
  it: { path: '/it/', ogLocale: 'it_IT' },
};
const KEY = 'gc-lang';        // saved choice, values 'en' | 'it'

const normalize = (v) => {
  const code = String(v || '').split('-')[0].toLowerCase();
  return Object.prototype.hasOwnProperty.call(LOCALES, code) ? code : null;
};

// first supported language in the browser's list decides; nothing supported means English
export function preferred(languages) {
  for (const l of languages || []) { const c = normalize(l); if (c) return c; }
  return 'en';
}

// all storage goes through try/catch: private mode and blocked storage behave like a first visit
const storeGet = (s, k) => { try { return s.getItem(k); } catch { return null; } };
const storeSet = (s, k, v) => { try { s.setItem(k, v); } catch { /* ignore */ } };
const local = () => { try { return globalThis.localStorage; } catch { return null; } };

export function savedLocale() {
  const s = local();
  return s ? normalize(storeGet(s, KEY)) : null;
}

export function saveLocale(code) {
  const c = normalize(code), s = local();
  if (c && s) storeSet(s, KEY, c);
}

let wired = false;
/** Call once on page start: wires the switcher. Returns the locale of the page that is shown. */
export function initI18n() {
  const doc = globalThis.document, loc = globalThis.location;
  if (!doc || !loc) return 'en';
  const current = normalize(doc.documentElement.lang) || 'en';
  if (!wired) {
    wired = true;
    doc.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[data-lang]') : null;
      if (!a) return;
      saveLocale(a.dataset.lang);
      if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
      e.preventDefault();
      loc.assign(a.getAttribute('href') + loc.hash);
    });
  }
  return current;
}

/** Switcher markup: two links, the active one marked with aria-current. languageLabel is C.ui.language.
 *  extraClass places the copy: the bar and the mobile menu each render one, CSS shows the one that fits. */
export function renderLangSwitch(current, languageLabel, extraClass = '') {
  const cur = normalize(current) || 'en';
  const links = Object.keys(LOCALES).map((code) =>
    `<a class="lang-link" href="${LOCALES[code].path}" lang="${code}" hreflang="${code}" data-lang="${code}"${code === cur ? ' aria-current="true"' : ''}>${code.toUpperCase()}</a>`
  ).join('<span class="lang-sep" aria-hidden="true">/</span>');
  const label = String(languageLabel || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
  return `<nav class="lang-switch${extraClass}" aria-label="${label}">${links}</nav>`;
}
